examples.code:
const option = 2;
switch (option) {
  case 1: console.log('Profile'); break;
  case 2: console.log('Settings'); break;
  case 3: console.log('Help'); break;
  default: console.log('Unknown option');
}

const status = 'paused';
switch (status) {
  case 'active': console.log('Running'); break;
  case 'paused': console.log('Waiting'); break;
  default: console.log('Status not recognized');
}

const level = 1;
switch (level) {
  case 1: console.log('Basic');
  case 2: console.log('Plus'); break;
  default: console.log('Other');
}

const temperature = 34;
if (temperature >= 35) {
  console.log('Very hot');
} else if (temperature >= 25) {
  console.log('Warm');
} else {
  console.log('Cool');
}

